def add_importance_concepts(apps, schema_editor):
    ConceptSchema = apps.get_model("vitrina_classifiers", "ConceptSchema")
    Concept = apps.get_model("vitrina_classifiers", "Concept")

    schema = ConceptSchema.objects.get(uri=IMPORTANCE_SCHEMA_URI)

    for data in importance_concepts_data:
        concept, created = Concept.objects.get_or_create(
            code=data["code"],
            defaults={
                "uri": data["uri"],
                "valid_since": data["valid_since"],
            },
        )
        if created:
            for lang, fields in data["translations"].items():
                concept.set_current_language(lang)
                concept.label = fields["label"]
                concept.description = fields.get("description", "")
            concept.save()
        concept.concept_schemas.add(schema)


