STATUS_CONCEPT = "http://purl.org/adms/status/"


def create_status_schema_and_concepts(apps, schema_editor):
    ConceptSchema = apps.get_model("vitrina_classifiers", "ConceptSchema")
    Concept = apps.get_model("vitrina_classifiers", "Concept")

    schema, created = ConceptSchema.objects.get_or_create(uri=STATUS_CONCEPT)
    if created:
        schema.set_current_language("lt")
        schema.label = "ADMS paslaugos statusas"
        schema.description = "E. paslaugos brandos lygmens statusas pagal ADMS specifikaciją"
        schema.save()
        schema.set_current_language("en")
        schema.label = "ADMS status"
        schema.description = "Asset maturity status as defined by the ADMS specification"
        schema.save()

    concepts_data = [
        {
            "uri": "http://purl.org/adms/status/Completed",
            "code": "ADMS_COMPLETED",
            "translations": {
                "en": {"label": "Completed", "description": "The asset is complete."},
                "lt": {"label": "Baigta", "description": "E. paslauga yra baigta."},
            },
        },
        {
            "uri": "http://purl.org/adms/status/Deprecated",
            "code": "ADMS_DEPRECATED",
            "translations": {
                "en": {"label": "Deprecated", "description": "The asset is deprecated."},
                "lt": {"label": "Pasenusi", "description": "E. paslauga yra pasenusi."},
            },
        },
        {
            "uri": "http://purl.org/adms/status/UnderDevelopment",
            "code": "ADMS_UNDER_DEVELOPMENT",
            "translations": {
                "en": {"label": "Under development", "description": "The asset is being developed."},
                "lt": {"label": "Kuriama", "description": "E. paslauga yra kuriama."},
            },
        },
        {
            "uri": "http://purl.org/adms/status/Withdrawn",
            "code": "ADMS_WITHDRAWN",
            "translations": {
                "en": {"label": "Withdrawn", "description": "The asset has been withdrawn."},
                "lt": {"label": "Atšaukta", "description": "E. paslauga yra atšaukta."},
            },
        },
    ]

    for data in concepts_data:
        concept, created = Concept.objects.get_or_create(
            uri=data["uri"],
            defaults={"code": data["code"], "valid_since": date(2013, 9, 9)},
        )
        if created:
            for lang, fields in data["translations"].items():
                concept.set_current_language(lang)
                concept.label = fields["label"]
                concept.description = fields["description"]
            concept.save()
        concept.concept_schemas.add(schema)


