def seed_spatial_coverages(apps, schema_editor):
    SpatialCoverage = apps.get_model("vitrina_classifiers", "SpatialCoverage")
    SpatialCoverage.objects.bulk_create(
        [
            SpatialCoverage(uuid=uuid.uuid4(), name=name, order=index)
            for index, name in enumerate(SPATIAL_COVERAGES)
        ],
        ignore_conflicts=True,
    )


